import * as React from "react"
import { Check, Copy } from "lucide-react"
import { type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { buttonVariants } from "@/components/ui/button-variants"

export type CopyButtonProps = Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  "children" | "onClick"
> &
  VariantProps<typeof buttonVariants> & {
    /** Texto (ou código) a ser copiado para a área de transferência. */
    value: string
    /** Label exibido ao lado do ícone. Default: "Copiar". */
    label?: string
    /** Callback disparado após copiar com sucesso. */
    onCopy?: () => void
    /** Duração (ms) do feedback visual. Default 2000. */
    feedbackMs?: number
  }

function CopyButton({
  value,
  label = "Copiar",
  onCopy,
  feedbackMs = 2000,
  variant = "outline",
  size = "sm",
  className,
  ...props
}: CopyButtonProps) {
  const [copied, setCopied] = React.useState(false)
  const timerRef = React.useRef<number | null>(null)

  const clearTimer = React.useCallback(() => {
    if (timerRef.current !== null) {
      window.clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }, [])

  React.useEffect(() => clearTimer, [clearTimer])

  const handleClick = React.useCallback(async () => {
    clearTimer()
    try {
      if (
        typeof navigator !== "undefined" &&
        navigator.clipboard &&
        typeof navigator.clipboard.writeText === "function"
      ) {
        await navigator.clipboard.writeText(value)
      } else {
        // Fallback: textarea temporário + execCommand
        const textarea = document.createElement("textarea")
        textarea.value = value
        textarea.setAttribute("readonly", "")
        textarea.style.position = "absolute"
        textarea.style.left = "-9999px"
        document.body.appendChild(textarea)
        textarea.select()
        const ok = document.execCommand("copy")
        document.body.removeChild(textarea)
        if (!ok) throw new Error("execCommand copy failed")
      }
      setCopied(true)
      onCopy?.()
      timerRef.current = window.setTimeout(() => {
        setCopied(false)
        timerRef.current = null
      }, feedbackMs)
    } catch {
      // Silently fail — o usuário pode tentar de novo
    }
  }, [value, feedbackMs, onCopy, clearTimer])

  const Icon = copied ? Check : Copy
  const displayLabel = copied ? "Copiado!" : label

  return (
    <button
      type="button"
      data-slot="copy-button"
      className={cn(
        buttonVariants({ variant, size }),
        "transition-colors",
        copied && "text-emerald-600 dark:text-emerald-400",
        className,
      )}
      onClick={handleClick}
      aria-live="polite"
      aria-label={displayLabel}
      {...props}
    >
      <Icon className="size-3.5" />
      {displayLabel}
    </button>
  )
}

export { CopyButton }

import { cva } from "class-variance-authority"

export const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive:
          "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-7 rounded-md gap-[normal] [&_svg:not([class*='size-'])]:size-3.5",
        "icon-sm": "size-8 rounded-md gap-[normal] [&_svg:not([class*='size-'])]:size-3.5",
        "icon-lg": "size-10 rounded-md gap-[normal] [&_svg:not([class*='size-'])]:size-5",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)
